import com.banking.domain.Exception.BankingException;

import java.util.ArrayList;
import java.util.List;

public class Account implements AccountService {

    private final DateProvider dateProvider;
    private final StatementPrinter printer;
    private final List<Transaction> transactions = new ArrayList<>();
    private int balance = 0;

    public Account(DateProvider dateProvider, StatementPrinter printer) {
        this.dateProvider = dateProvider;
        this.printer = printer;
    }

    @Override
    public void deposit(int amount) {
        if (amount <= 0) {
            throw new BankingException("Amount must be positive.");
        }
        balance += amount;
        transactions.add(new Transaction(dateProvider.today(), amount, balance));
    }

    @Override
    public void withdraw(int amount) {
        if (amount <= 0) {
            throw new BankingException("Amount must be positive.");
        }
        if (balance < amount) {
            throw new BankingException("Insufficient balance.");
        }
        balance -= amount;
        transactions.add(new Transaction(dateProvider.today(), -amount, balance));
    }

    @Override
    public void printStatement() {
        printer.print(transactions);
    }
}

import com.banking.domain.StatementPrinter;
import com.banking.domain.Transaction;

import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ConsoleStatementPrinter implements StatementPrinter {

    private static final String HEADER = "Date       | Amount | Balance";
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd-MM-yyyy");

    @Override
    public void print(List<Transaction> transactions) {
        System.out.println(HEADER);

        List<Transaction> copy = new ArrayList<>(transactions);
        Collections.reverse(copy);

        for (Transaction t : copy) {
            System.out.println(formatLine(t));
        }
    }

    private String formatLine(Transaction t) {
        return t.date().format(DATE_FORMAT) + " | " + t.amount() + " | " + t.balance();
    }
}

